+- Fix: stock is now used first-expired, first-out, so lots that expire sooner are used before newer ones.
 - Show stock on hand in `GET /items`.

 ## 2.3.0 - 2026-10-20
diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..46d254f 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -20,7 +20,13 @@ export function getBatch(store, id) {

 // The order in which an item's batches are used up.
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort(
+    (a, b) =>
+      (a.expires === null || a.expires === undefined) - (b.expires === null || b.expires === undefined) ||
+      (a.expires ?? "").localeCompare(b.expires ?? "") ||
+      a.receivedOn.localeCompare(b.receivedOn) ||
+      a.id - b.id,
+  );
 }

